(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gn"] = {"ui":{"skip":"Eho ñe'ẽme","back":"← Eho jey AI-gile-pe","lang.button":"Ñe'ẽ: {name}","lang.dialog":"Eiporavo peteĩ ñe'ẽ","lang.search":"Eheka ñe'ẽ","lang.none":"Ndaipóri ñe'ẽ ojojogua","lang.notYet":"{name} ndojehaijeporekái gueteri","theme.aria":"Emoambue tesaípe ha pytũmbýpe","theme.toLight":"Eho tesaípe","theme.toDark":"Eho pytũmbýpe","words.underline":"Emoĩ línea ko'ã ñe'ẽ guýpe ko kuatiaroguépe","words.underlineHelp":"Emoĩ mouse térã epoko peteĩ ñe'ẽ punteado ári rehecha haguã mba'épa he'ise.","index.title":"AI-gile: nde atyha AI, peteĩ tabla-pe","index.description":"AI-gile ha'e peteĩ kanban tabla atyha AI-pe oñehaíva código. Omba'apo reiko aja ereke; nde reñemoĩ ñemoĩ michĩ rehe: mba'e eikuaa haguã, eprueba haguã ha eaceptar haguã.","hero.logoAlt":"AI-gile tabla ta'anga","hero.h1.html":"Nde atyha AI, peteĩ&nbsp;tabla-pe.","hero.alpha":"🐣 Pre-alfa mboty","hero.alphaTitle":"Ojepyrũ gueteri ha ndopáiva: aguyje eprueba haguã!","hero.lede":"Omopu'ã reiko aja ereke. Reñepyrũ jey peteĩ ñemoĩ michĩ ndive: sa'i porandu, sa'i mba'e eprueba haguã, peteĩ térã mokõi diamante pytãngy. Eikutu, eaceptar, ha eho jey nde kafe-pe.","dl.windows":"Windows aplicación","dl.browser":"Eipuru nde navegador-pe","dl.soon":"Jepémo ndaikatúi","dl.notify":"🔔 Eñemomarandu aipo ojeipe'a vove","dl.notifySmall":"Alfa térã beta","hero.secondary":"Agile, ha katu atyha ndoikotevẽi kafe-ñepyrũ pukukue. (Péicha jepe ojapo.)","pitch.h2":"AI-gile oñe'ẽ hetaiterei ndive","pitch.lede":"Eiporavo pukukue, peteĩ ñe'ẽ guive 144 peve. Peteĩteĩ pukukue ha'e mba'e ojehaíva hese guarã. Emongu'e pe sliders térã eipuru flecha.","pitch.rangeLabel":"Pukukue ñe'ẽme","pitch.dice":"🎲 ambue versión","pitch.words.one":"{n} ñe'ẽ","pitch.words.other":"{n} ñe'ẽ","pitch.letters.one":"{n} tai","pitch.letters.other":"{n} tai","pitch.chars.one":"{n} tai","pitch.chars.other":"{n} tai","count.line.html.one":"{n} kuatia tabla-pe ko'ágã","count.line.html.other":"{n} kuatia tabla-pe ko'ágã","features.aria":"Mba'épa ojapo","f.pile.h":"Peteĩ ñemoĩ ndéve guarã","f.pile.html":"<b>Ndéve</b> oñongatu opa mba'e ndépe oha'arõva, opa tembiapo-pe: porandu, mba'e eprueba haguã, tembiapo ikatúva ojapo ha'e añoite. Nde fila he'i mba'e oúva ha mboy ára.","f.sleep.h":"Atyha omba'apóva reiko aja ereke","f.sleep.p":"Peteĩteĩ tembiapo oguereko peteĩ líder ha peteĩ atyha agente AI. Eñe'ẽ peteĩ kuatia-pe ha atyha oñemoĩ, ojapo pe tembiapo ha ombohasa jey ndéve tapykuépe ikatúva omuña peteĩ tapicha kane'õva.","f.tester.h":"Peteĩ AI tester ohecha raẽ","f.tester.p":"Oĩ mboyve ndéve, peteĩ tester oho tapykuépe peteĩ kopia aplicación-pe ha ohechauka mba'e ohecha, peteĩ pantalla ta'angapy ndive. Ehecha pe ojeheróva ha eaceptar peteĩ kutu-pe.","f.proof.h":"Hechaukapy, ndaha'éi ñe'ẽme'ẽ","f.proof.p":"Peteĩteĩ ñemoĩ ohechauka mba'e ojoko'i: umi marandu, pe diff, umi pantalla ta'angapy. Ndereikotevẽi embojuruja opa aplicación ehecha haguã ojejapopáma.","f.chat.h":"Eñe'ẽ nde líder kuérape","f.chat.p":"Peteĩ rail Discord-icha: peteĩ ta'anga peteĩteĩ tembiapo-pe guarã, diamante pytãngy mba'e ndéve oikotevẽvape guarã. Emondo ñemoñe'ẽ peteĩ líder-pe; ha'e ombojoapy kuatia ha peteĩ plan-pe, peteĩ ✅ Go votõ ndive.","f.tidy.h":"Ombyaty ijehe","f.tidy.p":"Umi kuatia joapýva oñembyaty peteĩme, umi téra ñembyaíva oñemoĩporã, ha peteĩ token jehecha ohecha pe código opyta hesakã. Sa'ive mba'e ojeiko hendápe, sa'ive mba'e ñepensa.","f.private.h":"Nde mba'e, nde mba'e'oka-pe","f.private.li1":"Pe tabla omba'apo nde máquina-pe ha ombohovái ndéve añoite.","f.private.li2":"DM ñemigua tapicha pa'ũme oñemigua pyteguápe.","f.private.li3":"Ndaipóri cuenta, ndaipóri tracker, ndaipóri cookie.","f.lang.h":"Nde ñe'ẽme","f.lang.p":"Hetave 120 ñe'ẽ, holandés, galés ha japonés guive pirata, Yoda ha klingon peve, ha peteĩ ñemoambue pya'e inglés-pe developer ñe'ẽ-rã.","tl.aria":"Ára tape ñe'ẽ ñepyrũ guive plan peve","tl.h2":"Ñepyrũ ñe'ẽ guive oúvape","tl.lede":"Árape ha aravopápe añete, nde zona horaria-pe. Ko árare guive ha'e plan, ndojepromeséiva árape.","tl.today":"Ko árape","tl.planned":"oñeplanea","tl.cards.one":"{n} kuatia","tl.cards.other":"{n} kuatia","join.h2":"Eñemoirũ","join.lede":"AI-gile oñemopu'ã peteĩ tapicha michĩ ha hetaiterei agente ipasiénsiavape. Ko'ágã ñemigua, peteĩ alfa mboty-pe angirũ ndive. Ndereipotái eprueba ojeipe'a vove?","join.btn":"Emoĩ ne interés","join.small":"Rehaíta ndéve email, ndaipóri hetave","footer.tag":"AI-gile. Ndaipóri tracker, ndaipóri cookie, ndaipóri kafe-ñepyrũ.","footer.licence":"Negocio licencia","footer.status":"Estado","footer.privacy":"Mba'épa ñañongatu","form.sending":"Ojejapo…","form.failed":"Péva ndojapói: eha'ã jey upéi.","form.offline":"Ndaikatúi ojejuhu AI-gile: eha'ã jey upéi.","form.keep":"Ñaipuru kóva ñambohovái haguãnte ndéve, upéi ñamboguete. Ndaipóri tracker, ndaipóri cookie.","form.keepLink":"Mba'épa ñañongatu","interest.title":"AI-gile: emoñe'ẽ chéve ojeipe'a vove alfa","interest.description":"Eheja nde email ehendu haguã araka'e ojeipe'a AI-gile alfa mboty térã beta.","interest.h1":"🔔 Emoñe'ẽ chéve ojeipe'a vove","interest.lede":"AI-gile oĩ pre-alfa mboty-pe. Eheja nde email ha rehaíta peteĩ jey, oĩ vove ndéve guarã tenda.","interest.email":"Nde email","interest.which":"Mba'e prueba?","interest.alpha":"Alfa mboty: ojepyrũ, ipiru'ã, hetaiterei ñemoambue","interest.beta":"Beta: hekopete ave, upéi","interest.both":"Mokõive, mba'e oúva raẽ","interest.submit":"Eñemoĩ chéve lista-pe","interest.thanks":"Aguyje! Reime lista-pe.","licence.title":"AI-gile: negocio licencia","licence.description":"Eipuru AI-gile nde negocio-pe? Eñemoĩ peteĩ licencia negocio mba'e'ỹre.","licence.h1":"📜 Negocio licencia","licence.lede":"Eipuru AI-gile tembiapo-pe? Emombe'u chéve máva ha mba'e rejapo. Ojapo ramo porã, pe licencia ndaipóri hepyrã.","licence.company":"Empresa","licence.website":"Sitio web","licence.what":"Mba'e rejapo","licence.how":"Mba'éichapa omoherakuã yvy","licence.email":"Email","licence.submit":"Emoĩ","licence.thanks":"Aguyje! Ñamboguata ndéve email rupi.","status.title":"AI-gile estado","status.h1":"AI-gile estado","status.quiet":"Opa mba'e kirirĩ","status.intro":"AI-gile omba'apópa ko'ágã? Ko kuatiarogue ohecha sitio web, tabla ñemoherakuã, ñehenói ha descarga káda 5 minuto.","status.up":"Omba'apo (ombohovái {ms} ms-pe)","status.slow":"Ndombohováii ñehecha pahápe, oñeha'ã jey","status.down":"Oñembyai: ndombohováii umi mokõi ñehecha pahápe","status.svc.web":"Sitio web","status.svc.web.offers":"Ko sitio: mba'épa AI-gile, ha formulario interés rehegua","status.svc.boards":"Tabla ñemoherakuã","status.svc.boards.offers":"Tabla opavavépe guarã, marandu angirũnguéra apytépe ha invitación","status.svc.calls":"Ñehenói","status.svc.calls.offers":"Ñe'ẽ, video ha pantalla ñemoherakuã AI-gile-pe","status.svc.download":"Descarga","status.svc.download.offers":"Windows instalador ha invitación enlace","status.checking":"Ojehecha…","status.offline":"Ko'ágã ndaikatúi ojejuhu estado servicio (oha'ã jey)","status.updated":"oñembopyahu {ago}","status.justNow":"ko'ágã","status.min":"{n} min rembýpe","status.hours":"{n} h rembýpe","status.days":"{n} ára rembýpe","privacy.title":"AI-gile: mba'épa ñañongatu","privacy.h1":"Mba'épa ñañongatu","privacy.lede":"Mbykyhápe: nde remondóva ñandéve añoite, ha ndaha'éi are guarã.","privacy.only":"Nde remondóva ñandéve añoite: rehaíva formulario-pe, ne email ramo. Ndaipóri ambue mba'e nderehegua.","privacy.sealed":"Oñemboty porã ani haguã ñane servidor omoñe'ẽ: ne navegador-pe osẽ mboyve (navegador tujavévape, og̃uahẽ vove). Ñane tabla añoite ikatu oipe'a.","privacy.server":"Oñemboguete servidor-gui og̃uahẽ rire ñane tabla-pe. Oĩramo gueteri upépe 30 ára rire, oñemboguete avei.","privacy.board":"Ñañongatu ñane tabla-pe ñambohovái peve ndéve, upéi ñamboguete upégui avei.","privacy.none":"Ndaipóri tracker, ndaipóri cookie, ndaipóri analítica.","privacy.local":"Ne ñe'ẽ ha ne poravo tesakã térã pytũ opyta ne navegador-pe. Araka'eve noñemondói ñandéve.","privacy.ask":"Reipotápa oñemboguete pya'eve? Embohovái ñane email ha ere ñandéve.","live.h2":"Ehecha ojejapo aja, hekoveve","live.caption":"Opaite kuatia ojeñomi: ehecha tembiapo ra’anga, ndaha’éi ñe’ẽ.","live.watching.one":"hekoveve: {n} ohecha","live.watching.other":"hekoveve: {n} ohecha","live.last.now":"Pe kárta ipahaitéva oñemoĩ ko'ágã","live.last.min.one":"Pe kárta ipahaitéva oñemoĩ {n} min ohasaramóva","live.last.min.other":"Pe kárta ipahaitéva oñemoĩ {n} min ohasaramóva","live.last.hour.one":"Pe kárta ipahaitéva oñemoĩ {n} aravo ohasaramóva","live.last.hour.other":"Pe kárta ipahaitéva oñemoĩ {n} aravo ohasaramóva","live.last.day.one":"Pe kárta ipahaitéva oñemoĩ {n} ára ohasaramóva","live.last.day.other":"Pe kárta ipahaitéva oñemoĩ {n} ára ohasaramóva","live.offline":"Tablero hekoveve ojepytuʼu sa’i. Eju jey pya’e.","live.cols":"Backlog|Ojejapótava|Ojejapóva|Atyha ohecháva|Ndéve ehecha haguã test|Atyha pe|Ojejapopáma"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Ojeheja."]},{"n":2,"texts":["Kanban robot.","Agente, organizado.","Mba'e, ojapóva."]},{"n":3,"texts":["Kanban robot-pe guarã.","Ñemoñe'ẽ ojeapo.","Agente kanban, mba'e'ỹre."]},{"n":5,"texts":["Kanban tabla agente omoñeñandúva.","Nde rehai kuatia. Agente ojapo.","Mba'e'ỹre, local, probado, sa'i tavy."]},{"n":8,"texts":["Peteĩ kanban tabla mba'e'ỹre, agente AI omba'apoha.","Ehai peteĩ ñemoñe'ẽ. Agente ojapo. Nde eaceptar.","Agile peteĩ tapicha ha hetaiterei robot ipasiénsiavape guarã."]},{"n":13,"texts":["Peteĩ kanban tabla nde mba'e'oka-pe, agente AI oipyhy hendápe kuatia.","Ehai peteĩ ñemoñe'ẽ. Peteĩ atyha agente ojapo. Peteĩ tester ohecha.","Mba'e'ỹre, ndaipóri cuenta ni tracker: peteĩ tabla, sa'i robot, ha nde remandúva."]},{"n":21,"texts":["AI-gile ha'e peteĩ kanban tabla ñemba'apo agente AI código ojapóva ndive. Ha'ekuéra oipyhy kuatia; nde eprueba ha eaceptar.","Peteĩteĩ tembiapo oguereko peteĩ líder ha peteĩ atyha agente AI. Eñe'ẽ oimeraẽ kuatia-pe ha atyha oñepyrũ pya'e omba'apo.","Peteĩ tabla personal mba'e'ỹre omba'apóva nde mba'e'oka-pe. Umi omba'apóva ha'e robot ha'ekuéra. Ha nde ha'e pe he'íva heẽ, tapiaite."]},{"n":34,"texts":["Reñemoĩ ne ñemoñe'ẽ peteĩ tabla-pe. Peteĩ atyha agente AI ombojoapy ha ojapo hese mba'e omba'apóva, oprueba mba'e ojejapo ha ombohasa jey ndéve tapykuépe eha'ã haguã. Mba'eve ndojejapopái nde ere peve, tapiaite.","AI-gile ha'e peteĩ kanban tabla ógape ojejapóva, Rich ojapo heta ñepytyvõ ndive umi agente ha'e ko'ágã ombohováiva. Ndaipóri hepyrã, omba'apo nde mba'e'oka-pe, ha oñemoherakuã angirũ ndive, ndaha'éi ojehepyme'ẽ haguã.","Eñeimo'ã peteĩ kanban tabla tembiguáipe, columna Backlog guive Ojejapopáma peve, ha katu kuatia oipyhy agente AI. Omombe'u mba'e oho, oporandu ojepyta vove, ha oha'arõ tapiaite nde heẽ."]},{"n":55,"texts":["AI-gile ha'e peteĩ kanban tabla, ha pe atyha ojejapo agente AI-gui. Peteĩteĩ tembiapo oguereko peteĩ líder oplanéava pe tembiapo ha oipytyvõva ojapóva ha'e pe ojapo haguã. Peteĩ tembiapo oĩ vove hembýva, peteĩ AI tester oprueba ha ojapo peteĩ pantalla ta'angapy, upéi ohupyty nde ñemoĩ. Eaceptar ko mba'e, térã eñe'ẽ ha ojapo jey hikuái.","Ojepyrũ peteĩ tapicha rape ha'e ohecha haguã hetaiterei sesión código AI ndive peteĩ jey, ha upéi okakuaa peteĩ tabla añete. Omba'apo nde máquina-pe, ndoikotevẽi cuenta, ha ndaipóri tracker. Ndaipóri hepyrã angirũ-pe ha oikuaasevape. Avei ndopái gueteri, upévare eha'arõ mba'e ipiru'ã ha sorpresa sa'i, ha upéva ndaha'éi mba'eve.","Péicha añete, ndahasýi. Ndéve reikotevẽ gueteri ñemoñe'ẽ, ha reikotevẽ gueteri rehecha umi ojejapóva. AI-gile ojapo opa mba'e ko'ã mokõi mbytépe: oñongatu kuatia hekopete, omopu'ã pe agente hekopete reñe'ẽ vove kuatia-pe, ohechauka mba'e ojoko'i, ha ombyaty opa mba'e peteĩ ñemoĩ mbykýpe ndéve guarã. Péicha ndereikotevẽi reikuaa'ỹ mba'e oiko, ha rereko ne ñe'ẽ ipahápe."]},{"n":89,"texts":["AI-gile ha'e peteĩ kanban tabla mba'e'ỹre reipurúva nde mba'e'oka-pe. Tapicha rãngue, peteĩteĩ tembiapo oguereko peteĩ atyha agente AI: peteĩ líder ombojoapýva ne ñemoñe'ẽ kuatia ha plan-pe, ha oipytyvõva oipyhy kuatia ojejapo vaerã peteĩ tape rupi. Peteĩ mba'e oñemopu'ã vove, peteĩ AI tester oho prueba tapykuépe ha ohechauka ndéve mba'e ohecha. Upéi oha'arõ peteĩ ñemoĩ-pe hérava Ndéve. Eaceptar, térã eñe'ẽ ha atyha oha'ã jey. Mba'eve ndoguahẽi Ojejapopáma-pe nde'ỹre, mba'eveichagua. Péicha ndéve ndaipóri ñemondo'ỹ, ha ndaipóri sorpresa vai.","Oĩ mba'e ndereha'arõiva avei. Peteĩ pyhare ñangareko ombyaty columna Ojejapótava rehegua reiko aja ereke, oiporavóva kuatia ndoikotevẽiva nde mbohovái. Peteĩ token jepapa ohechauka mboy ojeporu umi agente ko ára ha ko arapokõindy-pe, ha No Token Mode he'i chupe kuéra ani ojepuru hetave. Ikatu reñemondo marandu nde angirũ kuérape, ha marandu ñemigua oñemigua pyteguápe. Pe tabla oñe'ẽ 120 ñe'ẽ rupi, holandés, flamenco, pirata ha klingon ndive. Mba'eve ndohepýi, ha avave ndoheka ombohepy nde-pe.","AI-gile ha'e peteĩ tembiapo michĩ personal, ndaha'éi empresa. Rich oipota ñangareko hetaiterei tembiapo código AI rehegua ndaikotevẽi haguã embojuruja opa aplicación ehecha haguã mba'e oikóva hese, upévare ha'e ha umi agente ojapo peteĩ tabla upepe guarã, ha upéi oiporu pe tabla ojapo haguã opa ambue hembýva. Oĩ pre-alfa mboty-pe, he'ise omba'apo, hetáva, sa'i angirũ-pe guarã. Ndaipóri páhina hepyrã, ndaipóri boletín ha ndaipóri plan kakuaa. Ojeporu ramo ndéve, ikatu reporandu eprueba haguã ojeipe'a vove sa'ive, ha ñande ñeha'ã."]},{"n":144,"texts":["AI-gile ha'e peteĩ kanban tabla peteĩ tapicha ha hetaiterei agente AI-pe guarã. Omba'apo nde mba'e'oka-pe ha ndaipóri hepyrã mba'eveichagua. Reñemoĩ tembiapo, ha peteĩteĩ tembiapo oguereko peteĩ líder ha peteĩ atyha michĩ. Reñe'ẽ pe líder ndive, Discord-icha, ha emombe'u chupe peteĩ ñemoñe'ẽ; pe líder ombojoapy kuatia ha plan-pe, upéi oha'arõ reipytyvõ Go. Pe atyha omba'apo kuatia rupi tape rupi, peteĩ comando línea tembiguáipe ojejapóva ñe'ẽ modelo-pe guarã. Oĩ mboyve ñemoĩ ndéve, peteĩ AI tester oho tapykuépe peteĩ kopia aplicación-pe ha omoĩ hese peteĩ pantalla ta'angapy. Tembiapo opáva oguahẽ nde ñemoĩ-pe umi marandu ojoko'ívape ha pe diff ndive. Eaceptar, térã ehejá peteĩ ñe'ẽ ha pe atyha oñemoĩ jey ha oha'ã jey hikuái. Nde añoite ikatu emongu'e peteĩ kuatia Ojejapopáma-pe, avave ndaikatúi.","Peteĩ ára AI-gile ndive, sa'i ha sa'i. Ka'aru reheja sa'i ñe'ẽ: ko votõ ndaha'éi hendápe, ko lista oñemoĩ vaerã hekopete, ikatu piko jaguereko modo pytũ. Upéi reho reke. Umi agente omoñe'ẽ umi ñe'ẽ, ojapo umi ñemoambue, oprueba ha ombohasa jey ndéve. Ojejapótava opa ramo, pyhare ñangareko ombyaty ko'ã kuatia backlog-gui, ndoikotevẽiva nde mbohovái. Ko'ẽrõ oĩ peteĩ ñemoĩ mbyky ha michĩ: mokõi porandu ha sa'i mba'e eprueba haguã, peteĩteĩ tape ndive ikatúva omuña peteĩ tapicha ke'ỹ, ha peteĩ pantalla ta'angapy omba'apóva. Eikutu, eaceptar umi porãva ha emondo jey ambue. Peteĩ token jepapa ohechauka mboy ojeporu, ha No Token Mode oĩ ára michĩvape guarã. Upéi reñembojuka, ha umi agente ndaikatúi gueteri oipytyvõ upépe. Péicha opa ára oñepyrũ ha opa porã, ha nde reikuaa mba'e ojejapo.","Raẽ, mba'e AI-gile ndaha'éiva. Ndaha'éi startup, ndojehepyme'ẽi, ha avave ndombyaty nde dato. Ha'e peteĩ tabla mba'e'ỹre omba'apóva nde mba'e'oka-pe, ndaipóri cuenta, ndaipóri tracker ha ndaipóri cookie. Ha'e: peteĩ tenda hekopete ehecha haguã opa tembiapo código AI peteĩ jey, peteĩ atyha agente ojapóva umi kuatia ha nde ejapóva umi jeporavo. Ombyaty kuatia joapýva peteĩme, omoĩporã téra ñembyaíva, ha ohecha pe código opyta hesakã ha michĩ. Oñe'ẽ 120 ñe'ẽ rupi, holandés ha flamenco guive pirata ha klingon peve. Angirũ kuéra ikatu oñemondo marandu, ñemigua ha oñemigua pyteguápe. Rich ojapo hetaiterei agente ipasiénsiavape ndive, ojeporúva hekovépe ohóvo. Oĩ pre-alfa mboty-pe, upévare oĩ ipiru'ã ha'ekuéra. Ndéve ombovy'a ramo, eporandu porãme ha ikatu reike raẽ, ha ipyahu. Ñande ñemoirũ ha ñañemoĩ potĩ ñane rembiapo, sa'i sa'i, ha opa ára ñamba'apo."]}],"quips":{"1":"Peteĩ ñe'ẽ. Py'aguasu. Ikatu hetaiterei.","3":"Mbohapy ñe'ẽ. Ojeroviaha hetave heta producto páhina-gui.","8":"Mokõi ñe'ẽ ha irundy. Gueteri mbykyve peteĩ kafe-ñepyrũ-gui.","21":"Pukukue ha'e story point, upéicha. Ikatuha ndaha'éiramo.","55":"Cincuenta y cinco ñe'ẽ. Mokõi kuatia opa ereñe'ẽ aja ko'ã.","144":"Péva ha'e puku. Ndaipóri 233. Umi agente oho oke."}},"timeline":{"first-idea.name":"Ñemoñe'ẽ ñepyrũ","first-idea.line":"Ñe'ẽ ñepyrũ, ndaipóri mboyve código.","first-board.name":"Tabla ñepyrũ","first-board.line":"Peteĩ tabla ohecha hembiapo: kuatia, columna, jegueru ha mombyry, tembiapo.","team-roles.name":"Atyha ha tembiapo","team-roles.line":"Agente perfil, atyha plantilla, tenda ha máva ojapo mba'e.","install.name":"Ñemoĩ ha versión","install.line":"Peteĩ zip angirũ ikatúva omoĩ, ijehegui oñembopyahu, canal ha jeho jey.","usage-saver.name":"Jeporu ñeñongatu","usage-saver.line":"Emedí mboy hepy ojejapo, eñongatu código hesakã, eñongatu nde límite.","friends.name":"Angirũ ha ñemoherakuã","friends.line":"DM ñemigua, relé ñemigua, ñehenói, tembiapo ha tembiapo oñemoherakuãva.","languages.name":"Ñe'ẽ","languages.line":"Opa pantalla ñe'ẽ peteĩ ñe'ẽ marandu-pe, holandés ha flamenco raẽ.","ai-tester.name":"AI tester","ai-tester.line":"Peteĩ tester ohecha opa ñemoĩ raẽ ha ohechauka mba'e ohecha.","website.name":"Pe sitio web","website.line":"aigile.lol, pe teaser ha ko ára tape.","streaming.name":"Chat ha streaming","streaming.line":"Discord, Twitch, OBS, streamer modo, GIF ha emoji.","no-ai.name":"Edición AI'ỹre","no-ai.line":"Peteĩ tabla tapicha ojapóvape código AI'ỹre, ha tabla públicas.","night-watch.name":"Pyhare ñangareko","night-watch.line":"Peteĩ ñangarekohára ha Scrum Master omoĩ atyha tembiapo-pe reiko aja ereke.","p-more.name":"Opa ambue","p-more.line":"Ñemoñe'ẽ michĩvéva oha'arõva hendápe.","p-android.name":"Teléfono ha Android","p-android.line":"Eguahẽ nde tabla-pe teléfono-gui, upéi Android aplicación hekoite.","p-release.name":"Alfa ha upéi","p-release.line":"Alfa mboty, sitio oikovéva, upéi beta.","p-languages.name":"Hetave ñe'ẽ","p-languages.line":"Hetave cien ñe'ẽ, ha peteĩ inmersión modo oñemoñarõvape guarã.","p-engines.name":"Hetave AI motor","p-engines.line":"Eiporavo Claude, Codex térã Gemini peteĩteĩ agente-pe.","p-pro.name":"Profesional jepuru","p-pro.line":"Riesgo etiqueta, merge okẽ, incidente kuatia ha guardarraíl.","p-self.name":"Ñeñangareko ndejehe","p-self.line":"Kane'õ modo, ñeñangareko ñemomandu'a ha 4:20.","p-servers.name":"Servidor ha tuichakue","p-servers.line":"Servidor ñemoĩ opaite, tembiapo ha plan okakuaa haguã.","p-livestream.name":"Streaming ambue","p-livestream.line":"Twitch chat, emoji ijehegui ha jehecha pyahu público."},"words":{"button":"📖 Tembiapo ñe'ẽ","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Eheka peteĩ ñe'ẽ…","none":"Ndaipóri ñe'ẽ ojojáva.","close":"Emboty","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Tembiapo folder código ha ipype rembiasakue commit-pe, heta jey GitHub-pe avei.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Peteĩ rape tembiapo código-pe, ikatu haguã ojejapo ñemoambue ndojepokói hague pe versión tuicha.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Peteĩ ra'ãnga oñeñongatúva código-gui, marandu mbyky rehe mba'e oñemoambue. Ikatu reñemboguevi tapiaite peteĩme.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Emondo ra'ãnga oñeñongatúva (commit) ko mba'e'oka-gui GitHub-pe, oñeñongatu ha oñemoherakuã haguã."},{"id":"merge","g":"build","word":"Merge","text":"Ombojoaju branch ñemoambue pe versión tuicha-pe."},{"id":"pr","g":"build","word":"Pull request","text":"Ñe'ẽ ojerure branch ñemoambue ojehecha ha ojoaju pe versión tuicha-pe.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Emopotĩ código ndoguerohoryiva mba'e ojapo: marandu'i michĩve, réra hesakãvéva, sa'ive jehu jey."},{"id":"bug","g":"build","word":"Bug","text":"Mba'e ndoguatái oñeha'arõháicha.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Ehecha tembiapo ojejapopáma ojapo ramo oñeporandu haguã, eguerohory mboyve.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Emoĩ peteĩ versión pyahu oikove haguã, techapyrã peteĩ servidor-pe tapichakuéra oiporúva."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ñemoñe'ẽ ha tembiapo noñeplanéa gueteri. Mba'eve ndojejapói upépe ohasa peve Ojejapótava-pe."},{"id":"sprint","g":"team","word":"Sprint","text":"Peteĩ tembiapo mbyky (heta jey peteĩ térã mokõi arapokõindy) kuatia ojogueraha'ỹ oñemohu'ã haguã.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Peteĩ jehecha pya'e: mba'e ojapo peteĩ ha peteĩ pehẽngue, mba'e ojapota upéi, ha mba'e omboyke.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Peteĩ tabla kolumna reheve (Ojejapótava, Ojejapóva, Ojejapopáma) kuatia oho ← guive → gotyo tembiapo ojejapo aja."},{"id":"wip","g":"team","word":"WIP limit","text":"Tembiapo ojejapóva: kuatia hetavéva ikatúva oguereko peteĩ kolumna, atyha omohu'ã haguã mba'e oñepyrũ mboyve ambue.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"Peteĩ AI omba'apóva ijupe peteĩ tembiapo rehe: omoñe'ẽ código, ojapo ñemoambue, oguata jehecha ha omombe'u.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Pe unidad ojepapa AI jeporu: sa'i ñe'ẽ ojemoñe'ẽ térã ojehai. Sa'ive token, hetave nde plan hembýva.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Peteĩ komando michĩ oguatáva ijupe peteĩ mba'e jave, techapyrã AI sesión oñepyrũ jave, atyha ohendu haguã nde ñe'ẽ.","also":["hooks"]}]}};
